import { join } from "node:path";

/**
 * The placeholder app icon (generated by tooling/icon/generate.ts) until there is a logo. Windows takes the .ico for the
 * taskbar; Linux takes the png. macOS has no window icon: the dock gets the png through `applyDockIcon`.
 */
const assets = join(__dirname, "../assets");

export const appIconPath = (platform: NodeJS.Platform): string =>
  join(assets, platform === "win32" ? "icon.ico" : "icon.png");

/** The dock shows the app bundle's icon, which is Electron's until the app is packaged; set it while running. */
export function applyDockIcon(dock: { setIcon: (path: string) => void } | undefined, platform: NodeJS.Platform) {
  if (platform === "darwin") dock?.setIcon(join(assets, "icon.png"));
}
